def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (1, 9)]
    filled = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] in (1, 9):
                best = None
                bestdist = h + w
                counts = {}
                for rr, cc, color in src:
                    d = abs(r - rr) + abs(c - cc)
                    if d < bestdist:
                        bestdist = d
                        counts = {color: 1}
                    elif d == bestdist:
                        counts[color] = counts.get(color, 0) + 1
                if counts:
                    filled[r][c] = min(counts, key=lambda x: (-counts[x], x))

    return [[filled[h - 1 - c][r] for c in range(h)] for r in range(w)]
